$:node <<'NODE'
"use strict";
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{execFileSync}=require('node:child_process');
const repo='BestNameYet/Terminals';
const runs=[
 {id:41654917999,share:'6ae6b576-9fa8-83e8-a040-4091fe0218e3',request:'e2e008-distinct-small-20261103'},
 {id:41654917547,share:'6ae9dd85-7ff0-83e8-90c3-4592305a2362',request:'e2e008-distinct-large-20261103'}
];
const names=['response.html','conversation-raw.json','linear-conversation.json','conversation.json','conversation.md','diagnostics.json','receipt.json','execution.json'];
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const results=[];
for(const run of runs){
 const info=JSON.parse(execFileSync('gh',['api','repos/BestNameYet/Terminals/actions/runs/'+run.id],{encoding:'utf8'}));
 assert.equal(info.status,'completed');assert.equal(info.conclusion,'success');
 const dest='workspaces/shared-conversations/'+run.share+'/'+run.id+'-1';
 const receipt=JSON.parse(fs.readFileSync(path.join(dest,'receipt.json')));
 const execution=JSON.parse(fs.readFileSync(path.join(dest,'execution.json')));
 assert.equal(receipt.request_id,run.request);assert.equal(receipt.share_uuid,run.share);
 assert.equal(receipt.run_id,String(run.id));assert.equal(receipt.write_path,dest);
 assert.equal(execution.request_id,run.request);assert.equal(execution.errors.length,0);
 const sums=names.map(name=>{
  const buf=fs.readFileSync(path.join(dest,name));
  const digest=sha(buf);
  if(receipt.files[name]){
   assert.equal(receipt.files[name].sha256,digest);
   assert.equal(receipt.files[name].bytes,buf.length);
  }
  return {name,sha256:digest,bytes:buf.length};
 });
 const scratch=fs.mkdtempSync(path.join(os.tmpdir(),'e2e008-two-share-'));
 let att;
 try{
  execFileSync('gh',['run','download',String(run.id),'-R',repo,'--name','chatgpt-shared-export-final-attestation-'+run.id+'-1','--dir',scratch],{timeout:90000});
  att=JSON.parse(fs.readFileSync(path.join(scratch,'final-attestation.json')));
 }finally{fs.rmSync(scratch,{recursive:true,force:true});}
 assert.equal(att.verification,'VERIFIED');assert.equal(att.run_id,String(run.id));
 assert.equal(att.paths.length,8);assert.match(att.published_commit_sha,/^[0-9a-f]{40}$/);
 for(const f of att.paths){
  assert(f.path.startsWith(dest+'/'));const name=f.path.slice(dest.length+1);
  const match=sums.find(x=>x.name===name);assert(match);
  assert.equal(f.bytes,match.bytes);assert.equal(f.sha256,match.sha256);
  assert.equal(f.matched_remote_bytes,true);
 }
 results.push({id:run.id,share:run.share,request_id:run.request,created_at:info.created_at,started_at:info.run_started_at,completed_at:info.updated_at,files_verified:sums.length,commit:att.published_commit_sha,destination:dest,linear_nodes:receipt.counts.linear_nodes,visible_messages:receipt.counts.selected_visible_messages,verification:att.verification});
}
assert.notEqual(runs[0].share,runs[1].share);
assert.notEqual(results[0].destination,results[1].destination);
assert.notEqual(results[0].commit,results[1].commit);
const separation_ms=Math.abs(new Date(results[0].created_at)-new Date(results[1].created_at));
assert(separation_ms<=120000,'Dispatches were not sufficiently concurrent');
console.log(JSON.stringify({schema:'terminals.e2e008.two-distinct-shares.v1',test:'E2E-008',result:'PASS',dispatch_creation_separation_ms:separation_ms,run_count:2,verified_file_count:16,verified_attestations:2,distinct_share_count:2,runs:results},null,2));
